const {test}=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),vm=require('node:vm'),{execFileSync}=require('node:child_process');
const {parse}=require('../audits/audit-i18n-global.cjs'),root=path.resolve(__dirname,'../..'),read=f=>fs.readFileSync(path.join(root,f),'utf8'),base='a2f43e034e97d9f6ea8523bd3238bb921bf70b23',old=f=>execFileSync('git',['show',base+':'+f],{cwd:root,encoding:'utf8',maxBuffer:4e6});
function fn(source,name){const n=parse(source).body.find(n=>n.type==='FunctionDeclaration'&&n.id.name===name);assert.ok(n,name);return source.slice(n.start,n.end);}
function clean(n){if(!n||typeof n!=='object')return n;if(n.type==='IfStatement'&&n.consequent?.expression?.callee?.name==='appliquerTraductionsRP')return null;const c=n.expression;if(n.type==='ExpressionStatement'&&c?.type==='CallExpression'&&c.callee.object?.name==='msg'&&['setAttribute','removeAttribute'].includes(c.callee.property?.name)&&['data-i18n','data-i18n-values'].includes(c.arguments[0]?.value))return null;if(Array.isArray(n))return n.map(clean).filter(x=>x!==null);const o={};for(const [k,v]of Object.entries(n))if(!['start','end','loc','raw'].includes(k))o[k]=clean(v);return o;}
function cat(source){const c={};c.window=c;vm.createContext(c);vm.runInContext(read('i18n/resources.js'),c);vm.runInContext(source,c);return c.RP_I18N_RESOURCES;}
test('recherche : programme entier et authentification identiques hors annotations DOM',()=>{
 const pathProof=path.join(root,'outils/audits/I18N-RECHERCHE-PERSONNAGE-871-preuve.json'),proof=fs.existsSync(pathProof)?JSON.parse(fs.readFileSync(pathProof)):null;
 const source=proof?execFileSync('git',['show',proof.codeCommit+':creation.js'],{cwd:root,encoding:'utf8',maxBuffer:4e6}):read('creation.js');assert.deepEqual(clean(parse(source)),clean(parse(old('creation.js'))));
 const sourceFn=fn(read('creation.js'),'chargerPersonnageParNom');assert.equal((sourceFn.match(/msg.setAttribute\('data-i18n',/g)||[]).length,10);assert.equal((sourceFn.match(/if \(typeof appliquerTraductionsRP/g)||[]).length,10);
 const ref=proof?.codeCommit||execFileSync('git',['merge-base','HEAD','origin/main'],{cwd:root,encoding:'utf8'}).trim();assert.equal(execFileSync('git',['diff','--name-only',base,ref,'--','api','migrations','supabase','supabase.js','auth.js','data.js'],{cwd:root,encoding:'utf8'}),'');
});
test('recherche : français exact des cinq refus, anciennes ressources identiques, neuf langues et variables conservées',async()=>{
 const resources=cat(read('i18n/connection-resources.js')),before=cat(old('i18n/connection-resources.js')),langs=['fr','en','es','zh-TW','ru','ko','ar','pt-BR','de'],fr=resources.fr.translation.connectionUi;
 const cases=[['recoveryOwnedElsewhere',{raison:'personnage_deja_possede'}],['recoveryAlreadyOwns',{raison:'compte_deja_pourvu',personnage:'Nom <原 & اسم>'}],['recoveryAlreadyOwns',{raison:'compte_deja_pourvu'}],['recoveryOwnershipUnavailable',{raison:'http_404'}],['recoveryAccessDenied',{raison:'raison_libre <à conserver>'}],['recoveryAccessUnknown',{}]];
 for(const [key,verdict]of cases){const msg={style:{},textContent:''},b={document:{getElementById:()=>msg},t:()=>'',sbLoadPersonnage:async()=>({}),rpAuthAssurerSession:async()=>({}),rpAuthRattacherPersonnage:async()=>({ok:false,...verdict})};msg.value='Nom cherché';vm.createContext(b);vm.runInContext(fn(old('creation.js'),'chargerPersonnageParNom'),b);await b.chargerPersonnageParNom();const value=fr[key].replace('{{values.name}}',verdict.personnage||'').replace('{{values.reason}}',verdict.raison||'inconnu');assert.equal(value,msg.textContent,key);}
 for(const lang of langs){const now=resources[lang].translation.connectionUi;assert.ok(Object.keys(now).length>=18);for(const [key,value]of Object.entries(before[lang].translation.connectionUi))assert.equal(now[key],value);for(const key of Object.keys(fr).filter(k=>k.startsWith('recovery'))){assert.ok(now[key].trim());if(lang!=='fr')assert.notEqual(now[key],fr[key]);assert.deepEqual(now[key].match(/{{[^}]+}}/g)||[],fr[key].match(/{{[^}]+}}/g)||[]);}}
});
test('recherche : le moteur ne change que les données d’interpolation standard i18next',()=>{
 const normalize=n=>{if(!n||typeof n!=='object')return n;if(n.type==='Property'&&n.key.name==='replace'&&n.value.type==='ObjectExpression'&&n.value.properties[0]?.type==='SpreadElement'&&n.value.properties[0].argument.name==='values'&&n.value.properties[1]?.key.name==='values')return null;if(Array.isArray(n))return n.map(normalize).filter(x=>x!==null);const o={};for(const [k,v]of Object.entries(n))if(!['start','end','loc','raw'].includes(k))o[k]=normalize(v);return o;};const manifest=path.join(root,'outils/audits/I18N-RECHERCHE-PERSONNAGE-871-preuve.json'),ref=fs.existsSync(manifest)?JSON.parse(fs.readFileSync(manifest)).codeCommit:null;const source=ref?execFileSync('git',['show',ref+':i18n/i18n-init.js'],{cwd:root,encoding:'utf8'}):read('i18n/i18n-init.js');assert.deepEqual(normalize(parse(source)),normalize(parse(old('i18n/i18n-init.js'))));
});
